let html=`<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Auditoría de Carta · La Bella Lupita</title><style>
:root{color-scheme:light;--paper:#fbf7ef;--ink:#34241e;--muted:#6e5b50;--line:#dccfc0;--rose:#f4dcd3;--red:#9a3026;--green:#315b49}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.65 system-ui,sans-serif}a{color:#753b2b;text-underline-offset:.18em}a:focus-visible,button:focus-visible,select:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid #a63c64;outline-offset:4px}header{padding:54px max(24px,calc((100vw - 1120px)/2));background:#53291e;color:#fff7ed}header p{max-width:800px;color:#f4ddd2}h1{font:400 clamp(32px,4vw,54px)/1.16 Georgia,serif;max-width:850px;margin:10px 0 24px}h2{font:400 31px/1.3 Georgia,serif;margin:0 0 24px}h3{font-size:21px;line-height:1.4}header a{color:#fff7ed}.eyebrow{font-size:12px;letter-spacing:.15em;text-transform:uppercase}main{max-width:1170px;padding:0 24px;margin:auto}section{padding:40px 0;border-bottom:1px solid var(--line)}p{max-width:90ch}ul{padding-left:24px}li{margin:10px 0}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:30px}.metric{padding:16px;border:1px solid #987469}.metric b{display:block;font:400 30px Georgia,serif}.metric span{font-size:13px}.nav{display:flex;flex-wrap:wrap;gap:12px 24px;margin-top:26px}.nav a{font-size:14px}.filters{display:flex;flex-wrap:wrap;gap:16px;align-items:end;padding:20px;background:#f1e8dc;border-radius:6px;margin:20px 0}.filters label{font-size:13px;display:grid;gap:6px}.filters input,.filters select{font:inherit;font-size:15px;padding:12px;border:1px solid #95715c;border-radius:4px;background:white;min-height:46px}.filters input{min-width:230px}.status{font-size:14px;color:var(--muted)}details.finding{border:1px solid var(--line);border-radius:6px;margin:14px 0;background:#fffdf8}summary{cursor:pointer;padding:19px 22px;font-weight:600;line-height:1.4}summary::marker{color:#835341}.badge{display:inline-block;font-size:12px;padding:3px 8px;margin-right:10px;border-radius:20px;vertical-align:2px;background:#eae1d4}.P1{background:#f5ddd7;color:#832c22}.P2{background:#eee3c8;color:#6e4d16}.P3{background:#e0ebe3;color:#2c5140}.detail{padding:0 24px 24px}.meta{font-size:13px;color:var(--muted)}.detail p{margin:16px 0}.sources{font-size:13px;overflow-wrap:anywhere}.sources a{margin-right:12px}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;padding:14px 12px;border-bottom:1px solid var(--line);vertical-align:top}th{background:#f1e8dc;font-weight:600}.gallery{display:grid;grid-template-columns:1fr 1.8fr;gap:24px;align-items:start}.gallery img{width:100%;height:420px;object-fit:contain;object-position:top;background:#eee5d8;border:1px solid var(--line)}figure{margin:0}figcaption{font-size:13px;color:var(--muted);padding-top:10px}footer{padding:34px 24px;text-align:center;color:var(--muted);font-size:13px}.note{border-left:4px solid #a86d51;padding:12px 20px;background:#f3e9db}.download{display:inline-block;border:1px solid #c49a85;padding:9px 14px;border-radius:4px;text-decoration:none}button{font:inherit;padding:10px 14px;background:white;border:1px solid #95715c;border-radius:4px;min-height:44px;cursor:pointer}[hidden]{display:none!important}@media(max-width:700px){header{padding:30px 20px}main{padding:0 20px}.metrics{grid-template-columns:1fr 1fr}.gallery{grid-template-columns:1fr}.gallery img{height:400px}summary{padding:17px 15px}.detail{padding:0 16px 20px}.filters>*{width:100%}.filters input{min-width:0;width:100%}}@media print{header{background:white;color:black;padding:20px}header p,header a{color:black}.nav,.filters,button,.download{display:none}.metrics{margin-top:10px}.metric{border-color:#999}.detail{display:block}section{break-inside:auto}details{break-inside:avoid}main{max-width:none}.gallery img{height:280px}}
</style><header><div class="eyebrow">La Bella Lupita · 8 de octubre de 2026</div><h1>Auditoría integral de Carta</h1><p>Una base visual y transaccional útil, con brechas entre elegir, confirmar el precio y preparar el pedido. El diagnóstico distingue fallos reproducidos, riesgos del código y decisiones de operación.</p><div class="metrics"><div class="metric"><b>24</b><span>hallazgos agrupados</span></div><div class="metric"><b>5</b><span>prioridades P1</span></div><div class="metric"><b>73</b><span>productos auditados</span></div><div class="metric"><b>10 / 10</b><span>suites generales correctas</span></div></div><nav class="nav" aria-label="Contenido del informe"><a href="#diagnostico">Diagnóstico</a><a href="#hallazgos">Hallazgos</a><a href="#visual">Evidencia visual</a><a href="#plan">Plan de mejora</a><a href="#evidencia">Pruebas y fuentes</a><a href="INFORME-CARTA.md" class="download">Informe completo en Markdown</a></nav></header><main><section id="diagnostico"><h2>Diagnóstico y alcance</h2>${paras(intro)}<details><summary>Qué se verificó y qué límites tiene la evidencia</summary><div class="detail">${paras(alcance)}</div></details></section><section><h2>Lo que conviene conservar</h2><ul>${fortalezas.map(s=>'<li>'+esc(s)+'</li>').join('')}</ul></section><section id="hallazgos"><h2>Hallazgos y criterios de aceptación</h2><p>Filtrá por prioridad o perspectiva. Cada hallazgo incluye su evidencia, impacto, mejora y condición de cierre.</p><div class="filters"><label>Prioridad<select id="priority" aria-label="Prioridad"><option value="">Todas</option><option>P1</option><option>P2</option><option>P3</option></select></label><label>Perspectiva<select id="area" aria-label="Perspectiva"><option value="">Todas</option>${areas.map(a=>'<option>'+esc(a)+'</option>').join('')}</select></label><label>Buscar<input id="query" type="search" placeholder="Precio, foco, cocina…"></label><button id="expand" type="button">Expandir visibles</button></div><p id="count" class="status" role="status">24 hallazgos visibles</p>`;
for(const f of hallazgos)html+=`<details class="finding" data-priority="${f.p}" data-area="${esc(f.area)}" id="${f.id}"><summary><span class="badge ${f.p}">${f.p}</span>${f.id} · ${esc(f.titulo)}</summary><div class="detail"><p class="meta">${esc(f.area)} · ${esc(f.tipo)}</p><p>${esc(f.problema)}</p><p><strong>Impacto.</strong> ${esc(f.impacto)}</p><p><strong>Mejora.</strong> ${esc(f.mejora)}</p><p><strong>Criterio de aceptación.</strong> ${esc(f.aceptacion)}</p><p class="sources"><strong>Código:</strong> ${f.codigo.map(([p,l])=>esc(p)+':'+l).join(' · ')}</p><p class="sources"><strong>Evidencia:</strong> ${f.evidencia.map(p=>'<a href="'+esc(p)+'">'+esc(p.split('/').at(-1))+'</a>').join(' ')}${f.fuente?'<br><a href="'+esc(f.fuente[1])+'">'+esc(f.fuente[0])+'</a>':''}</p></div></details>`;
html+=`</section><section id="visual"><h2>La tarea queda lejos de los resultados</h2><div class="gallery"><figure><a href="evidencia/buscar-bagel-movil.png"><img src="evidencia/buscar-bagel-movil.png" alt="Buscar bagel en móvil conserva una fotografía de Latte y no muestra los resultados en la primera pantalla" loading="lazy"></a><figcaption>390×844. Buscador Y255; el bloque de resultados empieza en Y840, debajo de la navegación fija.</figcaption></figure><figure><a href="evidencia/carta-1024.png"><img src="evidencia/carta-1024.png" alt="Carta a 1024 píxeles muestra una fotografía grande antes del título y buscador" loading="lazy"></a><figcaption>1024×844. La composición coloca el destacado antes del título y del buscador; el campo empieza en Y920.</figcaption></figure></div><p>Coordenadas de apertura sin desplazamiento. En móvil el buscador sí precede al destacado; los estilos de casa.css cambian el orden definido en Carta.css.</p>${table(['Viewport','Buscador Y','Primer producto Y'],layout)}</section><section id="plan"><h2>Secuencia de mejora</h2><p>Orden por dependencias y riesgo, sin estimaciones de calendario que dependan de decisiones aún abiertas.</p>${table(['Fase','Resultado','Hallazgos','Responsabilidad sugerida','Puerta de salida'],fases)}<h3>Decisiones de operación</h3><ul>${decisiones.map(s=>'<li>'+esc(s)+'</li>').join('')}</ul></section><section><h2>Cómo medir si la mejora funciona</h2>${table(['Objetivo','Indicadores','Uso'],metricas)}${paras(cierre)}</section><section id="evidencia"><h2>Pruebas y fuentes</h2><p>Los 23 escenarios y 13 comprobaciones específicas dejaron evidencia. El resultado completed indica que el experimento terminó, no que la aplicación se comportara correctamente.</p><ul>${links.map(([n,p])=>'<li><a href="'+esc(p)+'">'+esc(n)+'</a></li>').join('')}</ul><p class="note">La evidencia de cobro usa cuentas sintéticas y PGlite. La coincidencia de assets verifica el cliente publicado; no certifica el backend desplegado. No se modificó la aplicación ni se enviaron pedidos o mensajes reales.</p><p><a href="INFORME-CARTA.md">Leer el informe completo y sus comandos de reproducción</a> · <a href="hallazgos.json">Descargar hallazgos estructurados</a></p></section></main><footer>La Bella Lupita · Auditoría de Carta · Evidencia del 8 de octubre de 2026</footer><script>
const cards=[...document.querySelectorAll('.finding')],priority=document.querySelector('#priority'),area=document.querySelector('#area'),query=document.querySelector('#query'),count=document.querySelector('#count');const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();function filter(){const q=normalize(query.value.trim());let n=0;for(const card of cards){card.hidden=!!((priority.value&&card.dataset.priority!==priority.value)||(area.value&&card.dataset.area!==area.value)||(q&&!normalize(card.textContent).includes(q)));if(!card.hidden)n++;}count.textContent=n+' '+(n===1?'hallazgo visible':'hallazgos visibles');}for(const el of[priority,area,query])el.addEventListener('input',filter);document.querySelector('#expand').addEventListener('click',()=>{const visible=cards.filter(c=>!c.hidden),open=visible.some(c=>!c.open);for(const c of visible)c.open=open;document.querySelector('#expand').textContent=open?'Contraer visibles':'Expandir visibles';});if(location.hash){const d=document.querySelector(location.hash);if(d?.tagName==='DETAILS')d.open=true;}window.addEventListener('beforeprint',()=>cards.forEach(c=>{c.hidden=false;c.open=true}));
</script></html>`;
writeFileSync(join(dir,'informe.html'),html);
console.log(JSON.stringify({hallazgos:hallazgos.length,prioridades:Object.fromEntries(['P1','P2','P3'].map(p=>[p,hallazgos.filter(f=>f.p===p).length])),markdownBytes:Buffer.byteLength(md),htmlBytes:Buffer.byteLength(html)}));

